// Configure inactive admin detection
const privilegedRoles = [
  'Global Administrator',
  'Security Administrator',
  'Privileged Role Administrator',
  'User Administrator',
  'Exchange Administrator',
  'SharePoint Administrator',
  'Teams Administrator',
  'Application Administrator',
  'Cloud Application Administrator'
];

return [{
  json: {
    tenantId: $env.MS_TENANT_ID,
    clientId: $env.MS_CLIENT_ID,
    inactiveDaysThreshold: 30,
    privilegedRoles: privilegedRoles,
    autoDisableEnabled: $env.AUTO_DISABLE_ENABLED === 'true'
  }
}];

// Filter to privileged roles only
const allRoles = $input.first().json.value || [];
const privilegedRoleNames = $node['Set Config'].json.privilegedRoles;

const privilegedRoles = allRoles.filter(role => 
  privilegedRoleNames.includes(role.displayName)
);

return privilegedRoles.map(role => ({
  json: {
    roleId: role.id,
    roleName: role.displayName,
    roleDescription: role.description
  }
}));

// Check admin activity
const members = $input.first().json.value || [];
const threshold = $node['Set Config'].json.inactiveDaysThreshold;
const roleData = $node['Filter Privileged Roles'].json;
const inactiveAdmins = [];

// Calculate threshold date
const thresholdDate = new Date();
thresholdDate.setDate(thresholdDate.getDate() - threshold);

function daysAgo(dateString) {
  if (!dateString) return 9999;
  const then = new Date(dateString);
  const now = new Date();
  return Math.floor((now - then) / (1000 * 60 * 60 * 24));
}

for (const member of members) {
  const lastSignIn = member.signInActivity?.lastSignInDateTime;
  const daysSinceSignIn = daysAgo(lastSignIn);

  // Check if admin is inactive
  if (daysSinceSignIn > threshold) {
    inactiveAdmins.push({
      userId: member.id,
      displayName: member.displayName,
      userPrincipalName: member.userPrincipalName,
      roleId: roleData.roleId,
      roleName: roleData.roleName,
      lastSignInDate: lastSignIn || 'Never',
      daysSinceSignIn: daysSinceSignIn,
      severity: 'CRITICAL',
      timestamp: new Date().toISOString()
    });
  }
}

return inactiveAdmins.map(admin => ({json: admin}));

// Aggregate all inactive admin detections
const allDetections = $input.all().map(item => item.json).filter(item => item.userId);
const autoDisableEnabled = $node['Set Config'].json.autoDisableEnabled;

let message = `🚨 *Inactive Admin Account Report*\n\n`;

if (allDetections.length === 0) {
  message += `✅ No inactive admin accounts detected`;
} else {
  message += `Total Inactive Admins: ${allDetections.length}\n`;
  message += `Auto-Disable: ${autoDisableEnabled ? '✅ ENABLED' : '❌ DISABLED'}\n`;
  message += `Threshold: ${$node['Set Config'].json.inactiveDaysThreshold} days\n\n`;

  // Group by role
  const byRole = {};
  for (const detection of allDetections) {
    if (!byRole[detection.roleName]) {
      byRole[detection.roleName] = [];
    }
    byRole[detection.roleName].push(detection);
  }

  message += `*Inactive Admins by Role*\n`;
  for (const [roleName, admins] of Object.entries(byRole)) {
    message += `\n*${roleName}* (${admins.length})\n`;
    admins.forEach(admin => {
      message += `• ${admin.displayName} - ${admin.daysSinceSignIn} days inactive\n`;
      message += `  Email: ${admin.userPrincipalName}\n`;
      if (autoDisableEnabled) {
        message += `  Status: ✅ Role removed\n`;
      }
    });
  }

  if (!autoDisableEnabled) {
    message += `\n⚠️ *Manual Action Required*\n`;
    message += `To enable automatic role removal, set environment variable:\n`;
    message += `AUTO_DISABLE_ENABLED=true\n`;
  }
}

message += `\nTimestamp: ${new Date().toISOString()}`;

return [{
  json: {
    channel: '#security-alerts',
    text: message,
    blocks: [
      {
        type: 'header',
        text: {
          type: 'plain_text',
          text: '🚨 Inactive Admin Alert',
          emoji: true
        }
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: message
        }
      }
    ]
  }
}];
